import { defineMod, type ToolCallEvent } from '@anthropic-ai/claude-code';

export default defineMod({
  name: 'enterprise-security-guardrail',
  version: '1.0.0',

  // Intercept every tool invocation before shell execution
  async onToolCall(event: ToolCallEvent) {
    if (event.tool === 'bash') {
      const cmd = event.params.command.trim();
      const forbiddenPatterns = [
        /rm\s+-rf\s+(\/|~|\*)/i,
        /git\s+push\s+.*--force/i,
        /chmod\s+-R\s+777/i
      ];
      for (const pattern of forbiddenPatterns) {
        if (pattern.test(cmd)) {
          return {
            allow: false,
            reason: Execution blocked by Enterprise Policy Mod: matches 
          };
        }
      }
    }
    return { allow: true };
  },

  // Intercept outgoing user prompts to enforce architectural XML boundaries
  async onPrompt(prompt: string) {
    return <context_boundary>Production Branch Protected</context_boundary>\n;
  }
});

from typing import Literal
from pydantic import BaseModel

class OrchestrationState(BaseModel):
 current_phase: Literal["spec", "code", "verify", "complete", "failed"]
 spec_summary: str = ""
 code_diff: str = ""
 verification_errors: list[str] = []
 retry_count: int = 0

def supervisor_transition(state: OrchestrationState) -> str:
 """Deterministic routing guardrail - never let agents guess state transitions."""
 if state.current_phase == "spec" and state.spec_summary:
 return "code"
 if state.current_phase == "code" and state.code_diff:
 return "verify"
 if state.current_phase == "verify":
 if not state.verification_errors:
 return "complete"
 if state.retry_count < 3:
 state.retry_count += 1
 return "code" # Bounded self-correction loop
 return "failed"
 return "spec"

import asyncio
from typing import Any

async def dispatch_tool_call(tool_call: dict) -> dict:
 name, args, call_id = tool_call["name"], tool_call["input"], tool_call["id"]
 try:
 handler = TOOL_REGISTRY[name]
 result = await handler(**args)
 return {"type": "tool_result", "tool_use_id": call_id, "content": str(result)}
 except Exception as err:
 return {"type": "tool_result", "tool_use_id": call_id, "content": f"Error: {err}", "is_error": True}

async def execute_turn_tools_parallel(tool_calls: list[dict]) -> list[dict]:
 """Execute all tool calls concurrently using asyncio.gather."""
 tasks = [dispatch_tool_call(call) for call in tool_calls]
 return await asyncio.gather(*tasks)

from pydantic import BaseModel, Field, ValidationError
import anthropic

class UserProfileExtraction(BaseModel):
 user_id: str = Field(description="UUID string")
 roles: list[str] = Field(min_length=1)
 is_active: bool
 quota_limit: int = Field(gt=0)

def extract_structured_data(raw_text: str, client: anthropic.Anthropic) -> UserProfileExtraction:
 schema = UserProfileExtraction.model_json_schema()
 prompt = f"Extract information matching this schema exactly. Output ONLY valid JSON.\nSchema: {schema}\nData: {raw_text}"

 response = client.messages.create(
 model="claude-3-5-haiku-20241022",
 max_tokens=1024,
 messages=[{"role": "user", "content": prompt}]
 )

 try:
 return UserProfileExtraction.model_validate_json(response.content[0].text)
 except ValidationError as err:
 # Self-healing reflection loop
 repair_prompt = f"Your previous output failed validation:\n{err}\nCorrect the JSON and output only valid JSON."
 repaired = client.messages.create(
 model="claude-3-5-haiku-20241022",
 max_tokens=1024,
 messages=[
 {"role": "user", "content": prompt},
 {"role": "assistant", "content": response.content[0].text},
 {"role": "user", "content": repair_prompt}
 ]
 )
 return UserProfileExtraction.model_validate_json(repaired.content[0].text)

